text:
Most common museum locales
The IMLS dataset also records the addresses of each museum and their associated NCES Urban-Centric Locale Codes classification. There are 4 levels: City (Territory inside an urbanized area and inside a principal city), Suburb (Territory inside an urbanized area but outside a principal city), Town (Territory inside an urban cluster that is outside an urbanized area) and Rural (Census-defined rural territory that is outside an urbanized area or urbanized cluster). The maps below show the most common of the four museum locales within each state.

Interactive map with leaflet


Code
# set up -----------------------------------------------------------------------
# creating a custom palette with viridis
pal &lt;- colorFactor(viridis(3, begin = 0.1, end = 0.9), domain = locale_sf$LOCALE4)

# creating labels
locale_sf &lt;- locale_sf |&gt;
  mutate(labels = str_c(State, "'s most common museum locale: ", LOCALE4))

# making labels html
labels &lt;- lapply(locale_sf$labels, HTML)

# making the dataframe class into sf so it can be used
locale_sf &lt;- st_as_sf(locale_sf)

# making a legend (data source) box
legend &lt;- "
&lt;style&gt;
  .custom-legend {
    background-color: rgba(255, 255, 255, 0.8);
    padding: 5px;
    border-radius: 5px;
    border: 1px solid #ddd;
    transition: background-color 0.3s, transform 0.3s;
    width: 300px;
  }
  .custom-legend:hover {
    background-color: rgba(255, 255, 255, 0.9);
    transform: scale(1.05);
  }
&lt;/style&gt;
&lt;div&gt;
 &lt;p&gt;
     Data source: Institute of Museum and Library Services, &lt;a href = https://www.imls.gov/research-evaluation/data/museum-data-files&gt;https://www.imls.gov/research-evaluation/data/museum-data-files&lt;/a&gt;
  &lt;/p&gt;
&lt;/div&gt;"

# leaflet map ------------------------------------------------------------------
leaflet(locale_sf) |&gt;
  setView(-96, 37.8, 4) |&gt;
  addTiles() |&gt;
  addPolygons(
    fillColor = ~pal(LOCALE4),
    weight = 2,
    opacity = 1,
    color = "white",
    dashArray = "3",
    fillOpacity = 0.7,
    highlightOptions = highlightOptions(
      weight = 5,
      color = "white",
      dashArray = "",
      fillOpacity = 0.7,
      bringToFront = TRUE),
    label = labels,
    labelOptions = labelOptions(
      style = list("font-weight" = "normal", padding = "3px 8px", color = "black"),
      textsize = "15px",
      direction = "auto")) |&gt;
  addLegend(pal = pal, values = ~LOCALE4, opacity = 0.7, title = NULL,
    position = "bottomright") |&gt;
  addControl(html = legend, position = "bottomleft", className = "custom-legend")






